REVOKE SELECT ON public.guardian_dispatches FROM anon, authenticated;
GRANT SELECT (id, guardian_height, directive, target_height, waypoints, started_at, ends_at, recalled_at, created_at, repeat) ON public.guardian_dispatches TO anon, authenticated;
REVOKE SELECT ON public.forge_modules FROM anon, authenticated;
GRANT SELECT (id, name, sphere, author_address, blocks, block_count, bit_cost, tribute_sats, lineage, uses, created_at) ON public.forge_modules TO anon, authenticated;
REVOKE SELECT ON public.community_kits FROM anon, authenticated;
GRANT SELECT (id, name, tagline, difficulty, maker_address, steps, bags, block_count, pay_txid, created_at, behaviors) ON public.community_kits TO anon, authenticated;
REVOKE SELECT ON public.bitmap_spawn_points FROM anon, authenticated;
GRANT SELECT (bitmap_height, x, z, yaw, owner_address, updated_at) ON public.bitmap_spawn_points TO anon, authenticated;
REVOKE SELECT ON public.oasis_voxels FROM anon, authenticated;
GRANT SELECT (x, y, z, kind, updated_at) ON public.oasis_voxels TO anon, authenticated;
COMMENT ON TABLE public.guardian_dispatches IS 'Public read intentional: every client derives Guardian positions from routes. Account ids hidden by column grants.';
COMMENT ON TABLE public.bitmap_spoils IS 'Public read intentional: raid outcomes are public, deterministic game results.';
COMMENT ON TABLE public.forge_modules IS 'Public read intentional: community pieces shown in the Forge. Account ids hidden.';
COMMENT ON TABLE public.bitmap_forge_builds IS 'Public read intentional: cache of builds verified from public Bitcoin inscriptions.';
COMMENT ON TABLE public.community_kits IS 'Public read intentional: published kit shelf. Account ids hidden.';
COMMENT ON TABLE public.bitmap_custody IS 'Public read intentional: cache of public on-chain satpoint facts.';
COMMENT ON TABLE public.genesis_minters IS 'Public read intentional: cache of public on-chain minter addresses.';
COMMENT ON TABLE public.bitmap_spawn_points IS 'Public read intentional: visitors need landing spots. Account ids hidden.';
COMMENT ON TABLE public.oasis_voxels IS 'Public read intentional: shared world blocks. Placer account ids hidden.';